using System.Text.Json.Serialization;

namespace Agentivity.Infrastructure.Workflow.Catalog.Domain.Layout;

/// <summary>
/// Generic content section generated by LLM.
/// Implements IContentSection for use with DocumentLayoutBuilder.
/// </summary>
public sealed class ContentSection : IContentSection
{
    [JsonPropertyName("id")]
    public string? Id { get; init; }

    [JsonPropertyName("title")]
    public string? Title { get; init; }

    [JsonPropertyName("level")]
    public int Level { get; init; } = 2;

    [JsonPropertyName("content")]
    public string? Content { get; init; }

    [JsonPropertyName("bullet_points")]
    public List<string>? BulletPointsList { get; init; }

    [JsonPropertyName("ordered")]
    public bool IsOrderedList { get; init; }

    [JsonPropertyName("image_refs")]
    public List<string>? ImageRefsList { get; init; }

    [JsonPropertyName("children")]
    public List<ContentSection>? ChildSections { get; init; }

    // IContentSection implementation
    IReadOnlyList<string> IContentSection.BulletPoints => BulletPointsList ?? [];
    IReadOnlyList<string> IContentSection.ImageRefs => ImageRefsList ?? [];
    IReadOnlyList<IContentSection> IContentSection.Children => ChildSections?.Cast<IContentSection>().ToList() ?? [];
}

/// <summary>
/// Container for content sections generated by LLM.
/// </summary>
public sealed class GeneratedContent
{
    [JsonPropertyName("sections")]
    public List<ContentSection> Sections { get; init; } = [];
}
